#[cfg(test)]mod local_avx2_kernel_tests{
 use super::*;
 struct Words{v:Vec<u8>,at:usize}impl XofReader for Words{fn read(&mut self,out:&mut[u8]){out.copy_from_slice(&self.v[self.at..self.at+out.len()]);self.at+=out.len();}}
 fn op(k:OperationType,a:u64,b:u64,t:u64,ct:u64,cc:u64)->Op{let mut o=Op::empty();o.kind=k;o.q_control2=QubitId(a);o.q_control1=QubitId(b);o.q_target=QubitId(t);o.c_target=BitId(ct);o.c_condition=BitId(cc);o.validate();o}
 #[test]fn avx2_all_operations_captured_guards_rng_and_toffoli_match_full_protected_simulator(){use OperationType as K;let n=u64::MAX;let ops=vec![op(K::X,n,n,2,n,0),op(K::Z,n,n,2,n,n),op(K::CX,n,0,3,n,1),op(K::CCX,0,1,4,n,n),op(K::CCZ,0,1,4,n,2),op(K::BitStore0,n,n,n,3,n),op(K::BitStore1,n,n,n,3,0),op(K::BitInvert,n,n,n,0,n),op(K::PushCondition,n,n,n,n,3),op(K::Swap,n,1,2,n,1),op(K::BitInvert,n,n,n,3,n),op(K::Hmr,n,n,4,2,1),op(K::CZ,n,0,1,n,2),op(K::R,n,n,5,n,0),op(K::PushCondition,n,n,n,n,2),op(K::X,n,n,3,n,n),op(K::PopCondition,n,n,n,n,n),op(K::PopCondition,n,n,n,n,n),op(K::Hmr,n,n,5,0,0),op(K::Neg,n,n,n,n,2)];let p=Compact::compile(&ops);let(nq,nb,_,_)=analyze_ops(ops.iter());for hi in 0..2{for pattern in 0..3{let mut q=vec![0;nq as usize*8];let mut b=vec![0;nb as usize*8];for j in 0..8{for lane in 0..64{for bit in 0..6{q[bit*8+j]|=(((lane>>bit)&1)as u64)<<lane;}}for bit in 0..4{b[bit*8+j]=if(((j|(hi<<3))>>bit)&1)!=0{u64::MAX}else{0};}}let rng:Vec<u64>=(0..p.rng_count*8).map(|i|match pattern{0=>0,1=>u64::MAX,_=>0x9e3779b97f4a7c15u64.wrapping_mul((i+1)as u64).rotate_left((i%64)as u32)}).collect();let initial_q=q.clone();let initial_b=b.clone();let mut phase=[0u64;8];let mut count=[0u64;8];let mut used=0;let mut stack=vec![0;32*8];assert_eq!(unsafe{simd8_run(p.ops.as_ptr(),p.ops.len(),q.as_mut_ptr(),b.as_mut_ptr(),phase.as_mut_ptr(),rng.as_ptr(),p.rng_count,stack.as_mut_ptr(),32,&mut used,count.as_mut_ptr())},0);assert_eq!(used,p.rng_count);for j in 0..8{let mut words=Words{v:(0..p.rng_count).flat_map(|i|rng[i*8+j].to_le_bytes()).collect(),at:0};let mut sim=Simulator::new(nq as usize,nb as usize,&mut words);for i in 0..nq as usize{sim.qubits[i]=initial_q[i*8+j];}for i in 0..nb as usize{sim.bits[i]=initial_b[i*8+j];}sim.apply_iter(ops.iter());for i in 0..nq as usize{assert_eq!(q[i*8+j],sim.qubits[i]);}for i in 0..nb as usize{assert_eq!(b[i*8+j],sim.bits[i]);}assert_eq!(phase[j],sim.phase);assert_eq!(count[j],sim.stats.toffoli_gates);drop(sim);assert_eq!(words.at,p.rng_count*8);}}}}
}
